package com.jamescornwell.seachartnavigator.model;

import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;

/** Immutable information needed to navigate to one sea charting task. */
public final class ChartingTask
{
	private final int id;
	private final String title;
	private final ChartingTaskType type;
	private final int completionVarbit;
	private final WorldPoint location;
	private final int requiredSailingLevel;

	public ChartingTask(
		int id,
		String title,
		ChartingTaskType type,
		int completionVarbit,
		WorldPoint location,
		int requiredSailingLevel
	)
	{
		this.id = id;
		this.title = title;
		this.type = type;
		this.completionVarbit = completionVarbit;
		this.location = location;
		this.requiredSailingLevel = requiredSailingLevel;
	}

	public int getId()
	{
		return id;
	}

	public String getTitle()
	{
		return title;
	}

	public ChartingTaskType getType()
	{
		return type;
	}

	public int getCompletionVarbit()
	{
		return completionVarbit;
	}

	public WorldPoint getLocation()
	{
		return location;
	}

	public int getRequiredSailingLevel()
	{
		return requiredSailingLevel;
	}

	public boolean isComplete(Client client)
	{
		return client.getVarbitValue(completionVarbit) != 0;
	}

	public boolean hasSailingLevel(int sailingLevel)
	{
		return sailingLevel >= requiredSailingLevel;
	}
}

package com.jamescornwell.seachartnavigator.ui;

import com.jamescornwell.seachartnavigator.SeaChartNavigatorConfig;
import com.jamescornwell.seachartnavigator.HudVisibility;
import com.jamescornwell.seachartnavigator.model.ChartingTask;
import com.jamescornwell.seachartnavigator.service.NavigationMath;
import com.jamescornwell.seachartnavigator.service.NavigationState;
import com.jamescornwell.seachartnavigator.service.SailingState;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Live directional overlay for the currently selected sea charting task. */
@Singleton
public class SeaChartNavigationOverlay extends Overlay
{
	private static final int ARROW_SIZE = 28;
	private static final int PADDING = 7;

	private final Client client;
	private final SeaChartNavigatorConfig config;
	private final NavigationState navigationState;

	@Inject
	public SeaChartNavigationOverlay(Client client, SeaChartNavigatorConfig config, NavigationState navigationState)
	{
		this.client = client;
		this.config = config;
		this.navigationState = navigationState;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.navigatorEnabled() || !shouldRenderHud())
		{
			return null;
		}

		ChartingTask target = navigationState.getTarget();
		WorldPoint playerLocation = SailingState.getTopLevelWorldPoint(client);
		if (target == null || playerLocation == null)
		{
			return null;
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		FontMetrics metrics = graphics.getFontMetrics();
		String title = target.getTitle();
		String activity = "Type: " + target.getType().getDisplayName() + " \u00b7 Sailing " + target.getRequiredSailingLevel();
		String distance = NavigationMath.tileDistance(playerLocation, target.getLocation()) + " tiles away";

		int textWidth = Math.max(metrics.stringWidth(title), Math.max(metrics.stringWidth(activity), metrics.stringWidth(distance)));
		int height = Math.max(ARROW_SIZE + (PADDING * 2), (metrics.getHeight() * 3) + (PADDING * 2));
		int width = ARROW_SIZE + (PADDING * 3) + textWidth;

		graphics.setColor(config.backgroundColor());
		graphics.fillRoundRect(0, 0, width, height, 8, 8);
		drawDirectionArrow(graphics, playerLocation, target.getLocation(), height);

		int textX = ARROW_SIZE + (PADDING * 2);
		int textY = PADDING + metrics.getAscent();
		graphics.setColor(Color.WHITE);
		graphics.drawString(title, textX, textY);
		graphics.setColor(new Color(208, 221, 216));
		graphics.drawString(activity, textX, textY + metrics.getHeight());
		graphics.drawString(distance, textX, textY + (metrics.getHeight() * 2));

		return new Dimension(width, height);
	}

	private boolean shouldRenderHud()
	{
		HudVisibility visibility = config.hudVisibility();
		return visibility == HudVisibility.ALWAYS ||
			(visibility == HudVisibility.WHEN_SAILING && SailingState.isSailing(client));
	}

	private void drawDirectionArrow(Graphics2D graphics, WorldPoint from, WorldPoint to, int height)
	{
		double angle = NavigationMath.cameraRelativeAngle(from, to, client.getCameraYaw());

		Graphics2D arrowGraphics = (Graphics2D) graphics.create();
		try
		{
			arrowGraphics.translate(PADDING + (ARROW_SIZE / 2.0), height / 2.0);
			arrowGraphics.rotate(angle);
			arrowGraphics.setColor(config.arrowColor());
			int halfWidth = ARROW_SIZE / 3;
			Polygon arrow = new Polygon(
				new int[]{0, -halfWidth, -halfWidth / 2, halfWidth / 2, halfWidth},
				new int[]{-ARROW_SIZE / 2, ARROW_SIZE / 3, ARROW_SIZE / 6, ARROW_SIZE / 6, ARROW_SIZE / 3},
				5
			);
			arrowGraphics.fillPolygon(arrow);
		}
		finally
		{
			arrowGraphics.dispose();
		}
	}
}

package com.jamescornwell.seachartnavigator.ui;

import com.jamescornwell.seachartnavigator.model.ChartingTask;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;

/** A single map marker for the current nearest target. */
public final class TargetMapPoint extends WorldMapPoint
{
	private final int taskId;

	public TargetMapPoint(ChartingTask task)
	{
		super(WorldMapPoint.builder()
			.worldPoint(task.getLocation())
			.image(createIcon())
			.tooltip("Nearest sea charting task: " + task.getTitle()));
		this.taskId = task.getId();
	}

	public int getTaskId()
	{
		return taskId;
	}

	private static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(18, 18, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setColor(new Color(0, 0, 0, 180));
			graphics.fillOval(1, 1, 16, 16);
			graphics.setStroke(new BasicStroke(2f));
			graphics.setColor(new Color(78, 219, 178));
			graphics.drawOval(2, 2, 14, 14);
			graphics.fillOval(7, 7, 4, 4);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}
}

package com.jamescornwell.seachartnavigator;

import com.google.inject.Provides;
import com.jamescornwell.seachartnavigator.model.ChartingTask;
import com.jamescornwell.seachartnavigator.service.ChartingTaskRepository;
import com.jamescornwell.seachartnavigator.service.NavigationState;
import com.jamescornwell.seachartnavigator.service.SailingState;
import com.jamescornwell.seachartnavigator.service.TargetSelector;
import com.jamescornwell.seachartnavigator.ui.SeaChartNavigationOverlay;
import com.jamescornwell.seachartnavigator.ui.TargetMapPoint;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

@PluginDescriptor(
	name = "Sea Chart Navigator",
	description = "Points to the nearest eligible sea charting task.",
	tags = {"sailing", "charting", "navigation", "sea"}
)
public class SeaChartNavigatorPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private SeaChartNavigatorConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SeaChartNavigationOverlay navigationOverlay;

	@Inject
	private WorldMapPointManager worldMapPointManager;

	@Inject
	private ChartingTaskRepository taskRepository;

	@Inject
	private TargetSelector targetSelector;

	@Inject
	private NavigationState navigationState;

	@Inject
	private Notifier notifier;

	private TargetMapPoint mapPoint;
	private boolean nativeHintArrowSet;
	private boolean arrivalNotificationSent;

	@Provides
	SeaChartNavigatorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SeaChartNavigatorConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(navigationOverlay);
		recalculateTarget(false, true);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(navigationOverlay);
		clearNavigation();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		recalculateTarget(true, false);
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.SAILING)
		{
			recalculateTarget(true, false);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (taskRepository.isCompletionVarbit(event.getVarbitId()))
		{
			recalculateTarget(true, false);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			recalculateTarget(false, true);
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			clearNavigation();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SeaChartNavigatorConfig.GROUP.equals(event.getGroup()))
		{
			recalculateTarget(false, true);
		}
	}

	private void recalculateTarget(boolean notifyOnChange, boolean forceDecorationRefresh)
	{
		if (!config.navigatorEnabled() || client.getGameState() != GameState.LOGGED_IN)
		{
			clearNavigation();
			return;
		}

		WorldPoint playerLocation = SailingState.getTopLevelWorldPoint(client);
		if (playerLocation == null)
		{
			clearNavigation();
			return;
		}

		int sailingLevel = config.useBoostedSailingLevel()
			? client.getBoostedSkillLevel(Skill.SAILING)
			: client.getRealSkillLevel(Skill.SAILING);

		ChartingTask previousTarget = navigationState.getTarget();
		ChartingTask selectedTarget = targetSelector.selectClosest(
			taskRepository.getTasks(),
			playerLocation,
			task -> task.hasSailingLevel(sailingLevel) && (config.includeCompleted() || !task.isComplete(client))
		);

		boolean targetChanged = previousTarget != selectedTarget;
		if (selectedTarget == null)
		{
			clearNavigation();
			return;
		}

		int distance = targetSelector.distance(playerLocation, selectedTarget.getLocation());
		navigationState.setTarget(selectedTarget);
		updateDecorations(selectedTarget, targetChanged || forceDecorationRefresh);

		if (targetChanged)
		{
			arrivalNotificationSent = false;
			if (notifyOnChange && config.targetNotifications().isEnabled())
			{
				notifier.notify(config.targetNotifications(), "Sea Chart Navigator: " + selectedTarget.getTitle());
			}
		}

		if (!arrivalNotificationSent && distance <= config.arrivalRadius())
		{
			arrivalNotificationSent = true;
			if (config.arrivalNotifications().isEnabled())
			{
				notifier.notify(config.arrivalNotifications(), "Sea Chart Navigator: You have reached " + selectedTarget.getTitle());
			}
		}
	}

	private void updateDecorations(ChartingTask target, boolean forceRefresh)
	{
		if (config.showWorldMapPin())
		{
			if (forceRefresh || mapPoint == null || mapPoint.getTaskId() != target.getId())
			{
				removeMapPoint();
				mapPoint = new TargetMapPoint(target);
				worldMapPointManager.add(mapPoint);
			}
		}
		else
		{
			removeMapPoint();
		}

		if (config.useNativeHintArrow())
		{
			if (forceRefresh || !nativeHintArrowSet)
			{
				client.setHintArrow(target.getLocation());
				nativeHintArrowSet = true;
			}
		}
		else
		{
			clearNativeHintArrow();
		}
	}

	private void clearNavigation()
	{
		navigationState.clear();
		arrivalNotificationSent = false;
		removeMapPoint();
		clearNativeHintArrow();
	}

	private void removeMapPoint()
	{
		if (mapPoint != null)
		{
			worldMapPointManager.remove(mapPoint);
			mapPoint = null;
		}
	}

	private void clearNativeHintArrow()
	{
		if (nativeHintArrowSet)
		{
			client.clearHintArrow();
			nativeHintArrowSet = false;
		}
	}
}

package com.jamescornwell.seachartnavigator.service;

import net.runelite.api.coords.WorldPoint;

/** Small, testable calculations used by the live navigation HUD. */
public final class NavigationMath
{
	private static final double FULL_CIRCLE_RADIANS = Math.PI * 2.0;
	private static final int CAMERA_YAW_UNITS = 2048;

	private NavigationMath()
	{
	}

	public static int tileDistance(WorldPoint from, WorldPoint to)
	{
		if (from == null || to == null)
		{
			return Integer.MAX_VALUE;
		}

		return Math.max(Math.abs(from.getX() - to.getX()), Math.abs(from.getY() - to.getY()));
	}

	/**
	 * Returns the target direction relative to the current camera view.
	 * A result of zero points straight up on screen.
	 */
	public static double cameraRelativeAngle(WorldPoint from, WorldPoint to, int cameraYaw)
	{
		if (from == null || to == null)
		{
			return 0.0;
		}

		double worldBearing = Math.atan2(to.getX() - from.getX(), to.getY() - from.getY());
		double cameraRadians = (cameraYaw & (CAMERA_YAW_UNITS - 1))
			* (FULL_CIRCLE_RADIANS / CAMERA_YAW_UNITS);
		double relativeBearing = worldBearing + cameraRadians;
		return Math.atan2(Math.sin(relativeBearing), Math.cos(relativeBearing));
	}
}

